<?= $this->section('scripts') ?>
<script>
(function(){const search=document.getElementById('companySearch'),source=document.getElementById('companySource'),listed=document.getElementById('companyListed'),rows=Array.from(document.querySelectorAll('.company-property-row'));function filter(){let count=0;const q=search.value.trim().toLocaleLowerCase();rows.forEach(function(row){row.hidden=!!((source.value&&row.dataset.source!==source.value)||(listed.value&&row.dataset.listed!==listed.value)||(q&&!row.textContent.toLocaleLowerCase().includes(q)));if(!row.hidden)count++;});document.getElementById('companyCount').textContent=count;document.getElementById('companyEmpty').hidden=count>0;}search.addEventListener('input',filter);source.addEventListener('change',filter);listed.addEventListener('change',filter);})();
</script>
